from lib import *
S = SS('s35')
steps = [
    step("最普通的抓取(起始页、a、b、一个 404、一个 302 跳到 a)结束时的 stats,逐项对账:downloader/request_count = 5(/、/a、/b、/missing、/redir),method_count/GET = 5;downloader/response_count = 5,按状态码拆成 200 × 3、302 × 1、404 × 1;而 response_received_count 只有 4——302 在下载器中间件阶段被重定向中间件消费掉,没有“收到响应”这件事;scheduler/enqueued = dequeued = 5,全部走 memory 队列;重定向到 /a 的请求被去重丢掉(dupefilter/filtered = 1);item_scraped_count = 2(a 和 b);request_depth_max = 1;log_count/INFO = 2;memusage/startup 与 max 都是 91,160,576 字节(一次很短的抓取里没有增长);finish_reason = finished。", t=tl(S(1)), mark=lidx(S(1), 'response_received_count', 'response_count', 'dupefilter/filtered', 'item_scraped_count'), done=lidx(S(1), 'request_count', 'scheduler/enqueued', 'finish_reason'), b=bars([['request_count', 5, '5'], ['response_count', 5, '5'], ['response_received_count', 4, '4'], ['item_scraped_count', 2, '2']], 5, mark=[2], done=[0, 1, 3]), kv=KV([['response_count 5', '含 302 和 404'], ['response_received_count 4', '302 被中间件消费,不算'], ['dupefilter/filtered 1', '重定向到已抓过的 /a'], ['item_scraped_count 2', 'a 和 b']], ['response_received_count 4'])),
    step("downloader/response_bytes 数的是线上响应的全部字节(头 + 体):原始套接字服务器发出的响应是 92 字节(头 77 + 体 15),stats 也是 92;20,000 字节页面发出 20,077 字节(头 80 + 体 19,997),stats 也是 20,077——两者完全相等。downloader/request_bytes 用的是请求的合成表示,不是线上字节:服务器实际收到 226 字节,stats 记 221 字节,差的 5 字节正好是 Host 头里的 “:端口”(合成表示的 Host 只写主机名)。", t=tl(S(2)), mark=lidx(S(2), 'request_bytes'), done=lidx(S(2), 'response_bytes'), b=bars([['服务器实际收到', 226, '226 字节'], ['request_bytes', 221, '221 字节']], 226, mark=[1], done=[0]), kv=KV([['response_bytes', '头 + 体,与线上字节完全一致(92 / 20,077)'], ['request_bytes', '合成表示:221,线上 226,差 Host 里的 “:端口” 5 字节']], ['request_bytes'])),
    step("自定义统计用 crawler.stats:inc_value('mine/pages') 累加(3 个页面 = 3);inc_value('mine/bytes', len(body), start=1000) 以起始值 1000 开始累加(最终 1135);set_value 直接写(mine/last_url = a);max_value / min_value 记最大最小(95 / 20);get_value('mine/none', 'DEFAULT') 取不到就用默认值;get_stats() 在第三次回调时已有 21 项。", t=tl(S(3)), mark=lidx(S(3), 'mine/'), kv=KV([['inc_value(key, count, start)', '累加,start 是初始值'], ['set_value', '直接设置'], ['max_value / min_value', '保留最大 / 最小'], ['get_value(key, default)', '取不到用默认值']], ['inc_value(key, count, start)'])),
    step("STATS_CLASS:换成 DummyStatsCollector 什么都不记,结束时仍打印 “Dumping Scrapy stats” 但内容为空,spider.closed() 里 get_stats() 是 0 项;STATS_DUMP = 0 只是不打印,统计照常收集(closed() 里仍有 20 项)。有趣的细节:默认情况下结束时日志里打出 25 项,而 spider.closed() 里读到的是 20 项——finish_time、finish_reason、elapsed_time_seconds 等几项是 spider_closed 信号之后才写入的。", t=tl(S(4)), mark=lidx(S(4), 'DummyStatsCollector', 'STATS_DUMP=0'), done=lidx(S(4), '默认 MemoryStatsCollector'), kv=KV([['Dummy', '不记任何统计,开销最小'], ['STATS_DUMP = 0', '不打印,统计照常收集'], ['25 vs 20', 'spider_closed 之后才补上 finish_* 等几项']], ['25 vs 20'])),
    step("DEBUG 级别的运行里,log_count 是 DEBUG 8、INFO 2(每个日志级别一个计数);memusage/startup 和 max 是 MemoryUsage 扩展记录的 RSS 字节数(约 90.8 MB);elapsed_time_seconds 与 finish_time − start_time 完全一致(0.0091 s 对 0.0091 s)。", t=tl(S(5)), mark=lidx(S(5), 'DEBUG 级别'), done=lidx(S(5), 'elapsed_time_seconds'), kv=KV([['log_count/<级别>', '每个日志级别的条数'], ['memusage/startup、max', 'RSS 字节数'], ['elapsed_time_seconds', '= finish_time − start_time']], ['log_count/<级别>'])),
]
A = mkarts('s35', 35, 'Scrapy,统计信息,stats,StatsCollector,request_bytes,真实验证,动画演示',
    '逐项对账 Scrapy 的 stats:5 个请求里 response_count 5 而 response_received_count 4(302 被中间件消费);response_bytes 与线上字节完全相等(92 / 20,077),request_bytes 比线上少 5 字节(Host 里的端口);自定义 inc_value/max_value;DummyStatsCollector 与 STATS_DUMP=0;结束日志 25 项而 spider.closed() 里 20 项。',
    '抓取结束时那一大串 stats 里的每个数字怎么来的?response_count 和 response_received_count 为什么不一样?bytes 数的是什么字节?怎么加自己的统计?这篇用一次很小的抓取把 stats 逐项对账。',
    [('5 vs 4', 'downloader/response_count 与 response_received_count(302 被重定向中间件消费)'), ('226 vs 221', '服务器实际收到的请求字节与 downloader/request_bytes(差 Host 里的 “:端口”)'), ('25 vs 20', '结束日志里的统计项数与 spider.closed() 里读到的项数')],
    [('请求与响应计数', '<p><code>downloader/request_count</code>、<code>response_count</code> 由下载器统计中间件记;<code>response_received_count</code> 是引擎发出 <code>response_received</code> 信号的次数,被重定向、重试中间件消费掉的响应不算。</p>'),
     ('字节数', '<p><code>response_bytes</code> 是线上头加体的字节数;<code>request_bytes</code> 来自请求的合成文本(Host 头不带端口),比线上略短。</p>'),
     ('自定义统计', '<p><code>crawler.stats</code> 提供 <code>inc_value</code>、<code>set_value</code>、<code>max_value</code>、<code>min_value</code>、<code>get_value</code>、<code>get_stats</code>。</p>'),
     ('关闭统计', '<p><code>STATS_CLASS</code> 换成 <code>DummyStatsCollector</code> 完全不记;<code>STATS_DUMP = 0</code> 只是不在结束时打印。</p>'),
     ('其它', '<p><code>log_count/*</code> 按日志级别计数,<code>memusage/*</code> 来自 MemoryUsage 扩展,<code>elapsed_time_seconds</code> 等于结束时间减开始时间。</p>')],
    steps,
    [ENV_Y + '。第一节抓取:起始页链接到 /a、/b、/missing(404)、/redir(302 → /a);第二节用原始套接字服务器对照真实字节;并发默认',
     '没有验证:PERIODIC_LOG_STATS 周期性日志;stats 在 CrawlerProcess 多个 crawler 之间是否隔离;STATS_CLASS 自定义实现;大量请求时 MemoryStatsCollector 的内存;memusage 在 Linux 上的取值方式(这里是 macOS);httperror/*、retry/*、robotstxt/* 等专题统计见各自文章'],
    '统计')
